// Clean up the URL and work out the registrable domain (handles common two-part suffixes like co.uk).
const TWO = ['co.uk', 'org.uk', 'me.uk', 'ltd.uk', 'plc.uk', 'ac.uk', 'gov.uk', 'net.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.za',
  'co.jp', 'com.br', 'com.mx', 'co.in', 'com.cn', 'com.sg', 'com.hk', 'com.tr', 'co.kr', 'com.ar', 'com.my', 'com.ph', 'co.id'];
return $input.all().map(item => {
  const j = item.json;
  let raw = String(j.url || '').trim().match(/(https?:\/\/)?[a-z0-9.-]+\.[a-z]{2,}[^\s<>"']*/i)?.[0] || '';
  if (raw && !/^https?:\/\//i.test(raw)) raw = 'https://' + raw;
  // plain string parsing (the URL class is not available in every n8n Code sandbox)
  const rest = raw.replace(/^https?:\/\//i, '');
  const host = (rest.split(/[\/?#]/)[0] || '').replace(/:\d+$/, '').replace(/^[^@]*@/, '').toLowerCase().replace(/\.$/, '');
  const path = rest.slice(rest.split(/[\/?#]/)[0].length) || '/';
  const valid = /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host) && /[a-z]{2,}$|^\d+\.\d+\.\d+\.\d+$/.test(host);
  const parts = host.split('.');
  const two = parts.slice(-2).join('.');
  const three = parts.slice(-3);
  const domain = TWO.includes(two) && parts.length >= 3 && three[0] !== 'www' ? three.join('.') : two;
  return { json: { ...j, url: raw, host, domain, valid, https_url: valid ? 'https://' + host + (path.startsWith('/') ? path : '/' + path) : '',
    http_url: valid ? 'http://' + host + '/' : '', checked_at: new Date().toISOString() } };
});

// Facts first: turn the raw checks into signals and a 0-100 risk score. The AI later explains these; it does not set the score.
const PRO = false;
const s = $('Set checker settings').first().json;
const base = $('Normalise the URL').all();
const pick = (name, i) => { try { return $(name).all()[i]?.json ?? null; } catch (e) { return null; } };
const SUS_TLD = ['zip', 'mov', 'top', 'xyz', 'icu', 'click', 'gq', 'tk', 'ml', 'cf', 'ga', 'buzz', 'rest', 'cam', 'sbs', 'cfd', 'bond', 'cyou', 'monster', 'quest', 'lol'];
const BRANDS = ['paypal', 'apple', 'amazon', 'microsoft', 'netflix', 'google', 'facebook', 'instagram', 'whatsapp', 'royalmail', 'dhl', 'fedex', 'ups', 'hmrc', 'coinbase', 'binance', 'metamask', 'ebay', 'barclays', 'hsbc', 'natwest', 'lloyds', 'santander', 'chase', 'wellsfargo'];
const daysSince = d => { const t = Date.parse(String(d).replace(/^(\w{3}) /, '')); return isFinite(t) ? Math.floor((Date.now() - t) / 864e5) : null; };
return base.map((b, i) => {
  const u = b.json;
  const red = [], green = [], facts = {};
  let risk = 0;
  const add = (pts, msg) => { risk += pts; red.push(msg); };
  if (!u.valid) return { json: { ...u, risk_score: null, risk_level: 'unknown', red_flags: ['Not a valid web address, so nothing could be checked'], green_flags: [], facts: {} } };
  // --- domain name itself
  const tld = u.domain.split('.').pop();
  if (/^\d+\.\d+\.\d+\.\d+$/.test(u.host)) add(20, 'The address is a bare IP number, not a domain name');
  if (u.host.includes('xn--')) add(15, 'Uses an internationalised (punycode) domain that can imitate other letters');
  if (SUS_TLD.includes(tld)) add(10, `.${tld} domains are cheap and common in scams`);
  if ((u.domain.match(/-/g) || []).length >= 2) add(5, 'Domain has several hyphens');
  const tokens = u.host.split(/[.-]/);
  const brand = BRANDS.find(br => tokens.includes(br) && !u.domain.startsWith(br + '.'));   // e.g. paypal-secure-login.shop
  if (brand) add(25, `Mentions "${brand}" but the site is not on ${brand}'s own domain`);
  // --- domain age (RDAP)
  let rd = pick('Look up domain age (RDAP)', i) || {};
  if (typeof rd.data === 'string') { try { rd = JSON.parse(rd.data); } catch (e) {} }   // some registries answer as application/rdap+json text
  const ev = Array.isArray(rd.events) ? rd.events : [];
  const reg = ev.find(e => e.eventAction === 'registration')?.eventDate;
  const exp = ev.find(e => e.eventAction === 'expiration')?.eventDate;
  const registrar = (rd.entities || []).find(e => (e.roles || []).includes('registrar'))?.vcardArray?.[1]?.find(v => v[0] === 'fn')?.[3] || '';
  const age = reg ? daysSince(reg) : null;
  facts.domain_registered = reg ? String(reg).slice(0, 10) : 'unknown'; facts.domain_age_days = age; facts.registrar = registrar;
  facts.domain_expires = exp ? String(exp).slice(0, 10) : 'unknown';
  if (age === null) add(5, 'Domain age could not be confirmed (registry gave no date)');
  else if (age < 30) add(35, `Domain registered only ${age} days ago`);
  else if (age < 90) add(25, `Domain registered ${age} days ago (under 3 months)`);
  else if (age < 365) add(10, `Domain is less than a year old (${age} days)`);
  else if (age >= 1825) { risk -= 10; green.push(`Domain registered ${Math.floor(age / 365)} years ago`); }
  else green.push(`Domain is ${Math.floor(age / 365)}+ year(s) old`);
  if (exp && daysSince(exp) !== null && -daysSince(exp) < 60 && age !== null && age < 400) add(5, 'Domain is registered for only about a year (expires soon)');
  // --- page fetch, HTTPS, headers
  const pg = pick('Fetch the page', i) || {};
  const st = Number(pg.statusCode) || 0;
  const headers = Object.fromEntries(Object.entries(pg.headers || {}).map(([k, v]) => [k.toLowerCase(), String(v)]));
  const html = String(pg.body ?? pg.data ?? '');
  facts.http_status = st || 'no response';
  if (!st || pg.error) add(15, 'The site did not load over HTTPS');
  else if (st >= 400) add(10, `The page answered with HTTP ${st}`);
  else green.push('Loads over HTTPS');
  const sec = { 'strict-transport-security': 'HSTS', 'content-security-policy': 'CSP', 'x-frame-options': 'X-Frame-Options',
    'x-content-type-options': 'X-Content-Type-Options', 'referrer-policy': 'Referrer-Policy', 'permissions-policy': 'Permissions-Policy' };
  const present = Object.keys(sec).filter(h => headers[h]);
  facts.security_headers = present.map(h => sec[h]).join(', ') || 'none';
  if (st && st < 400) { if (present.length <= 1) add(5, 'Almost no security headers'); else if (present.length >= 4) green.push(`${present.length} of 6 security headers set`); }
  if (headers['server']) facts.server = headers['server'];
  // --- page content
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ');
  const low = text.toLowerCase(), hl = html.toLowerCase();
  const links = [...hl.matchAll(/<a\b[^>]*href="([^"]*)"[^>]*>([\s\S]*?)<\/a>/g)].map(m => (m[1] + ' ' + m[2].replace(/<[^>]+>/g, '')).toLowerCase());
  const has = rx => links.some(l => rx.test(l)) || rx.test(low);
  facts.title = (html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1] || '').replace(/\s+/g, ' ').trim().slice(0, 140);
  facts.words = low.split(' ').filter(Boolean).length;
  if (html) {
    const email = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.test(text), phone = /(\+?\d[\d\s().-]{8,}\d)/.test(text);
    const contact = links.some(l => /contact|kontakt|about/.test(l));
    facts.contact = [contact && 'contact/about page', email && 'e-mail', phone && 'phone'].filter(Boolean).join(', ') || 'none';
    if (!contact && !email && !phone) add(15, 'No contact page, e-mail address or phone number found');
    else green.push('Contact details: ' + facts.contact);
    const privacy = has(/privacy|datenschutz|gdpr/), terms = has(/terms|conditions|agb/);
    if (!privacy) add(5, 'No privacy policy link'); 
    if (privacy && terms) green.push('Privacy policy and terms linked');
    const shop = /add to (cart|basket|bag)|checkout|buy now|shopping (cart|bag|basket)|your (cart|basket|bag)/.test(low);
    facts.looks_like_shop = shop;
    if (shop) {
      if (!has(/refund|return|exchange|widerruf/)) add(10, 'Sells products but has no returns/refund policy link');
      const company = /company (no|number|reg)|registered in (england|scotland|wales)|vat (no|number|reg)|\bein\b|\babn\b|registered office|handelsregister|siret|kvk/.test(low);
      if (!company) add(5, 'Shop shows no company registration or VAT number'); else green.push('Shows company registration / VAT details');
      const off = [...low.matchAll(/(\d{2})\s?% off/g)].map(m => +m[1]);
      if (off.some(x => x >= 70)) add(10, `Extreme discounts (up to ${Math.max(...off)}% off)`);
    }
    if (/western union|moneygram|gift ?cards? (only|as payment)|pay (only )?(by|with) (bitcoin|crypto|bank transfer)|bank transfer only|crypto only|zelle only|friends and family/.test(low)) add(25, 'Asks for hard-to-refund payment (bank transfer, crypto, gift cards or money transfer)');
    if (/only \d+ left|limited time|offer ends|act now|hurry|last chance|today only/.test(low)) add(5, 'Pressure / urgency wording');
    if (/verify your (account|identity)|account (suspended|locked)|confirm your (password|card)|enter your (password|card number)/.test(low)) add(20, 'Phishing-style wording (verify / suspended account / enter password)');
    const yr = Math.max(0, ...[...text.matchAll(/(?:©|&copy;|copyright)\s*(?:\d{4}\s*[-–]\s*)?(20\d{2})/gi)].map(m => +m[1]));
    if (yr && yr < new Date().getFullYear() - 2) add(3, `Copyright notice is out of date (${yr})`);
    if (facts.words < 80) add(5, 'Very little text on the page');
  }
  if (PRO) {
    // --- final URL / redirect, plain http
    const fin = String(pg.headers?.['x-final-url'] || '');
    const plain = pick('Check HTTP to HTTPS redirect', i) || {};
    const loc = String((plain.headers || {}).location || '');
    facts.http_redirects_to_https = /^https:/i.test(loc);
    if (plain.statusCode && !/^https:/i.test(loc) && Number(plain.statusCode) < 400) add(5, 'Plain http:// does not redirect to https://');
    if (loc && /^https?:\/\//i.test(loc)) { const h = loc.replace(/^https?:\/\//i, '').split(/[\/?#:]/)[0].toLowerCase(); if (h && !h.endsWith(u.domain)) add(10, `Redirects to a different domain (${h})`); }
    // --- certificate transparency (Cert Spotter)
    const ct = pick('Check TLS certificate history', i) || {};
    let certs = []; try { certs = JSON.parse(ct.data || ct.body || '[]'); } catch (e) {}
    if (Array.isArray(certs) && certs.length) {
      const first = certs.map(c => daysSince(c.not_before)).filter(x => x !== null).sort((a, b) => b - a)[0];
      const latest = certs[certs.length - 1];
      facts.first_certificate_days_ago = first ?? 'unknown';
      facts.certificate_issuer = latest.issuer?.friendly_name || latest.issuer?.name || '';
      facts.certificate_expires = String(latest.not_after || '').slice(0, 25);
      if (first !== null && first !== undefined && first < 30) add(10, `First HTTPS certificate issued only ${first} days ago`);
      else if (first > 365) green.push(`HTTPS certificates on record for ${Math.floor(first / 365)}+ year(s)`);
    } else facts.first_certificate_days_ago = 'unknown';
    // --- Google Safe Browsing (optional)
    const sb = pick('Check Google Safe Browsing', i);
    if (sb && !sb.error) {
      const m = sb.matches || [];
      facts.safe_browsing = m.length ? m.map(x => x.threatType).join(', ') : 'no match';
      if (m.length) { risk = Math.max(risk, 100); red.unshift('Google Safe Browsing lists this site: ' + facts.safe_browsing); }
      else green.push('Not on Google Safe Browsing lists');
    } else facts.safe_browsing = s.safe_browsing_api_key ? 'check failed' : 'not checked (no API key)';
  }
  risk = Math.max(0, Math.min(100, Math.round(risk)));
  const level = risk >= 50 ? 'high' : risk >= 25 ? 'medium' : 'low';
  return { json: { ...u, risk_score: risk, risk_level: level, red_flags: red, green_flags: green, facts } };
});

parameters.text:
=You explain website safety checks to a non-technical person who is about to buy from, sign up to, or pay a supplier through this site{{ $json.context ? ' (context: ' + $json.context + ')' : '' }}.

Site: {{ $json.host }}
Risk score (computed from the checks, do not change it): {{ $json.risk_score }}/100 = {{ $json.risk_level }} risk
Red flags: {{ JSON.stringify($json.red_flags) }}
Good signs: {{ JSON.stringify($json.green_flags) }}
Facts: {{ JSON.stringify($json.facts) }}

Write:
- verdict: one short sentence matching the {{ $json.risk_level }} risk level.
- summary: 2-3 sentences in plain English on what the checks found.
- top_concerns: up to 3 of the most important red flags in your own words (empty if none).
- advice: 2-3 concrete next steps (e.g. pay by credit card for chargeback protection, search the company number, look for independent reviews).
Do not claim the site IS a scam or IS safe: these are signals, not proof. Use only the data above.

parameters.jsonSchemaExample:
{
  "verdict": "High risk: treat this shop with caution.",
  "summary": "The domain was registered 12 days ago and the shop shows no company details or returns policy, while advertising 80% discounts.",
  "top_concerns": [
    "Brand-new domain",
    "No way to contact the seller",
    "Discounts that look too good to be true"
  ],
  "advice": [
    "Don't pay by bank transfer; use a credit card or PayPal Goods & Services.",
    "Search the shop name plus 'reviews' or 'scam' before ordering."
  ]
}

