const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Build the report in three shapes: HTML page (form), Telegram message, Sheets row.
const checks = $('Score the risk signals').all().map(i => i.json);
return $input.all().map((item, i) => {
  const c = checks[i] || {}; const a = item.json.output || {};
  const icon = { low: '🟢', medium: '🟠', high: '🔴' }[c.risk_level] || '⚪';
  const score = c.risk_score === null || c.risk_score === undefined ? 'n/a' : c.risk_score + '/100';
  const verdict = c.valid === false ? 'This is not a valid web address, so it could not be checked.' : (a.verdict || `${c.risk_level} risk (${score})`);
  const f = c.facts || {};
  const factRows = Object.entries(f).filter(([k, v]) => v !== '' && v !== null && v !== undefined)
    .map(([k, v]) => `<tr><td style="color:#64748b;padding:2px 10px 2px 0">${esc(k.replace(/_/g, ' '))}</td><td>${esc(v)}</td></tr>`).join('');
  const ul = xs => (xs || []).map(x => `<li>${esc(x)}</li>`).join('');
  const html = `<div style="font-family:Arial,sans-serif;max-width:680px"><h2>${icon} ${esc(c.host || c.url)}: ${esc(c.risk_level)} risk (${score})</h2>
<p><b>${esc(verdict)}</b></p><p>${esc(a.summary || '')}</p>
${(c.red_flags || []).length ? `<h3>Red flags</h3><ul>${ul(c.red_flags)}</ul>` : ''}${(c.green_flags || []).length ? `<h3>Good signs</h3><ul>${ul(c.green_flags)}</ul>` : ''}
${(a.advice || []).length ? `<h3>What to do</h3><ul>${ul(a.advice)}</ul>` : ''}<h3>Checks</h3><table style="font-size:13px">${factRows}</table>
<p style="color:#94a3b8;font-size:12px">Automated signals, not proof either way. Checked ${esc(c.checked_at)}.</p></div>`;
  const tg = `${icon} <b>${esc(c.host || c.url)}</b>: <b>${esc(c.risk_level)}</b> risk (${score})\n${esc(verdict)}\n\n` +
    ((c.red_flags || []).length ? '🚩 ' + c.red_flags.slice(0, 6).map(esc).join('\n🚩 ') + '\n' : '') +
    ((c.green_flags || []).length ? '✅ ' + c.green_flags.slice(0, 4).map(esc).join('\n✅ ') + '\n' : '') +
    ((a.advice || []).length ? '\n💡 ' + a.advice.map(esc).join('\n💡 ') : '') + '\n\n<i>Automated signals, not proof.</i>';
  const row = { checked_at: c.checked_at, url: c.url, domain: c.domain, risk_score: c.risk_score, risk_level: c.risk_level, verdict,
    red_flags: (c.red_flags || []).join(' | '), green_flags: (c.green_flags || []).join(' | '), domain_age_days: f.domain_age_days ?? '',
    registrar: f.registrar || '', safe_browsing: f.safe_browsing || '', source: c.channel, requested_by: c.requested_by || '' };
  return { json: { ...row, channel: c.channel, chat_id: c.chat_id, row_number: c.row_number, html, tg: tg.slice(0, 4000), row } };
});
